18	extern "C" __global__ __aicore__ void kv_sort(
19	    GM_ADDR keys, GM_ADDR values, GM_ADDR sortedKeys, GM_ADDR sortedValues,
20	    GM_ADDR workspace, GM_ADDR tiling)
21	{
22	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
23	    if (g_coreType == AIC) {
24	        return;
25	    }
26	
27	    auto* gmTiling = reinterpret_cast<__gm__ SortKernelTiling*>(tiling);
28	    SortKernelTiling t;
29	    t.tilingMode = gmTiling->tilingMode;
30	    t.totalLength = gmTiling->totalLength;
31	    t.sortNum = gmTiling->sortNum;
32	    t.coreNum = gmTiling->coreNum;
33	    t.perCoreElements = gmTiling->perCoreElements;
34	    t.lastCoreElements = gmTiling->lastCoreElements;
35	    t.perCoreLoops = gmTiling->perCoreLoops;
36	    t.lastCoreLoops = gmTiling->lastCoreLoops;
37	    t.perCorePerLoopElements = gmTiling->perCorePerLoopElements;
38	    t.lastCorePerLoopElements = gmTiling->lastCorePerLoopElements;
39	    t.perCoreLastLoopElements = gmTiling->perCoreLastLoopElements;
40	    t.lastCoreLastLoopElements = gmTiling->lastCoreLastLoopElements;
41	    t.oneLoopMaxElements = gmTiling->oneLoopMaxElements;
42	    t.needCoreNum = gmTiling->needCoreNum;
43	
44	    if (t.tilingMode == SORT_TILING_MODE_FULLLOAD) {
45	        TPipe pipe;
46	        SortFullLoad op;
47	        op.Init(keys, values, sortedKeys, sortedValues, &t, &pipe);
48	        op.Process();
49	    } else if (t.tilingMode == SORT_TILING_MODE_SINGLECORE) {
50	        TPipe pipe;
51	        SortOneCore op;
52	        op.Init(keys, values, sortedKeys, sortedValues, &t, &pipe);
53	        op.Process();
54	    } else if (t.tilingMode == SORT_TILING_MODE_MULTICORE) {
55	        TPipe pipe;
56	        SortMultiCore op;
57	        op.Init(keys, values, sortedKeys, sortedValues, workspace, &t, &pipe);
58	        op.Process();
59	        pipe.Destroy();
60	    }
61	}
