#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_topk_float.h"
#include "aclrtlaunch_topk_half.h"
#include "aclrtlaunch_topk_bfloat16.h"
#include "topk_tiling.h"

namespace ascend_kernel {

constexpr int32_t NUM_CORES = 20;
constexpr int32_t SORT_ALIGN = 32;  // Sort requires 32-element alignment

static void computeTiling(TopkTilingData* t, int64_t totalSlices, int32_t sliceLen, int32_t k, int32_t largest, int32_t dtypeSize)
{
    *t = TopkTilingData{};
    t->totalSlices = totalSlices;
    t->sliceLen = sliceLen;
    t->k = k;
    t->largest = largest;
    t->dtypeSize = dtypeSize;

    // Align sliceLen to 32 for Sort
    int32_t alignedLen = ((sliceLen + SORT_ALIGN - 1) / SORT_ALIGN) * SORT_ALIGN;
    t->alignedSliceLen = alignedLen;

    // Calculate core allocation
    int32_t coreNum = std::min<int32_t>(NUM_CORES, static_cast<int32_t>(totalSlices));
    if (coreNum < 1) coreNum = 1;
    t->coreNum = coreNum;

    int32_t slicesPerCore = static_cast<int32_t>((totalSlices + coreNum - 1) / coreNum);
    t->slicesPerCore = slicesPerCore;
    t->lastCoreSlices = static_cast<int32_t>(totalSlices - static_cast<int64_t>(slicesPerCore) * (coreNum - 1));
    if (t->lastCoreSlices <= 0) {
        t->lastCoreSlices = slicesPerCore;
    }
}

at::Tensor topk(const at::Tensor& self, int64_t k, int64_t dim, bool largest)
{
    TORCH_CHECK(self.is_contiguous(), "topk: input must be contiguous");
    TORCH_CHECK(k > 0, "topk: k must be positive");
    TORCH_CHECK(k <= self.size(dim), "topk: k must be less than or equal to the size of the dimension");

    int64_t ndim = self.dim();
    if (dim < 0) {
        dim = ndim + dim;
    }
    TORCH_CHECK(dim >= 0 && dim < ndim, "topk: dim out of range");

    // Compute output shape
    std::vector<int64_t> outShape(self.sizes().begin(), self.sizes().end());
    outShape[dim] = k;

    // Create output tensor
    auto output = at::empty(outShape, self.options());

    // If dim is not the last dimension, we need to transpose to make it last
    at::Tensor inputContig = self;
    at::Tensor outputContig = output;
    bool needTranspose = (dim != ndim - 1);

    if (needTranspose) {
        // Transpose dim to the last position
        std::vector<int64_t> perm(ndim);
        for (int64_t i = 0; i < ndim; ++i) {
            perm[i] = i;
        }
        perm[dim] = ndim - 1;
        perm[ndim - 1] = dim;
        inputContig = self.permute(perm).contiguous();
        outputContig = at::empty(inputContig.sizes(), self.options());
    }

    // Now dim is the last dimension
    int64_t sliceLen = inputContig.size(-1);
    int64_t totalSlices = inputContig.numel() / sliceLen;

    // Flatten all but last dimension
    auto inputFlat = inputContig.reshape({totalSlices, sliceLen});
    auto outputFlat = outputContig.reshape({totalSlices, k});

    // Compute tiling
    int32_t dtypeSize = 0;
    if (self.scalar_type() == at::kFloat) {
        dtypeSize = 4;
    } else if (self.scalar_type() == at::kHalf) {
        dtypeSize = 2;
    } else if (self.scalar_type() == at::kBFloat16) {
        dtypeSize = 2;
    } else {
        TORCH_CHECK(false, "topk: unsupported dtype");
    }

    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(TopkTilingData))},
        at::device(at::kCPU).dtype(at::kByte));
    auto* tiling = reinterpret_cast<TopkTilingData*>(tilingCpu.data_ptr());
    computeTiling(tiling, totalSlices, static_cast<int32_t>(sliceLen),
                  static_cast<int32_t>(k), largest ? 1 : 0, dtypeSize);

    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    uint32_t blockDim = static_cast<uint32_t>(tiling->coreNum);

    // Launch kernel based on dtype
    if (self.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(topk_float, blockDim, inputFlat, outputFlat, tilingNpu);
    } else if (self.scalar_type() == at::kHalf) {
        EXEC_KERNEL_CMD(topk_half, blockDim, inputFlat, outputFlat, tilingNpu);
    } else if (self.scalar_type() == at::kBFloat16) {
        EXEC_KERNEL_CMD(topk_bfloat16, blockDim, inputFlat, outputFlat, tilingNpu);
    }

    // If we transposed, need to transpose back
    if (needTranspose) {
        // Transpose last dimension back to original dim position
        std::vector<int64_t> permBack(ndim);
        for (int64_t i = 0; i < ndim; ++i) {
            permBack[i] = i;
        }
        permBack[ndim - 1] = dim;
        permBack[dim] = ndim - 1;

        // Reshape outputFlat back to multi-dim before permute
        auto outputReshaped = outputFlat.reshape(inputContig.sizes());
        output = outputReshaped.permute(permBack).contiguous();
    } else {
        output = outputFlat.reshape(outShape);
    }

    return output;
}

}  // namespace ascend_kernel
