67	template <typename T>
68	__aicore__ inline void KernelTopk<T>::Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling) {
69	    // Read tiling data from GM
70	    auto* gmTiling = reinterpret_cast<__gm__ TopkTilingData*>(tiling);
71	    tilingData.totalSlices = gmTiling->totalSlices;
72	    tilingData.sliceLen = gmTiling->sliceLen;
73	    tilingData.k = gmTiling->k;
74	    tilingData.largest = gmTiling->largest;
75	    tilingData.coreNum = gmTiling->coreNum;
76	    tilingData.slicesPerCore = gmTiling->slicesPerCore;
77	    tilingData.lastCoreSlices = gmTiling->lastCoreSlices;
78	    tilingData.dtypeSize = gmTiling->dtypeSize;
79	    tilingData.alignedSliceLen = gmTiling->alignedSliceLen;
80	
81	    // Set GM tensors
82	    inputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(input));
83	    outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(output));
84	
85	    // Calculate buffer sizes
86	    int32_t alignedLen = tilingData.alignedSliceLen;
87	    // sort buffer: alignedLen floats for values + alignedLen floats for indices
88	    int32_t sortBufSize = alignedLen * sizeof(float) * 2;
89	    // output buffer: k elements
90	    int32_t outBufSize = tilingData.k * sizeof(T);
91	
92	    // Init queues
93	    pipe.InitBuffer(inQueue, BUFFER_NUM, sortBufSize);
94	    pipe.InitBuffer(outQueue, BUFFER_NUM, outBufSize);
95	}
