97	template <typename T>
98	__aicore__ inline void KernelTopk<T>::CopyIn(int32_t sliceIdx) {
99	    int64_t srcOffset = static_cast<int64_t>(sliceIdx) * tilingData.sliceLen;
100	    int32_t sliceLen = tilingData.sliceLen;
101	    int32_t alignedLen = tilingData.alignedSliceLen;
102	
103	    // Get input buffer from queue
104	    auto inBuf = inQueue.AllocTensor<float>();
105	
106	    // Fill with -inf for padding (first alignedLen floats are values)
107	    float negInf = -3.402823466e+38f;
108	    Duplicate(inBuf, negInf, alignedLen);
109	    WaitVDone();
110	
111	    // Copy actual data from GM to UB
112	    if (sliceLen > 0) {
113	        if constexpr (std::is_same_v<T, float>) {
114	            // FP32: direct copy
115	            DataCopyExtParams copyParams(
116	                static_cast<uint16_t>(1),
117	                static_cast<uint32_t>(sliceLen * sizeof(float)),
118	                static_cast<uint32_t>(0),
119	                static_cast<uint32_t>(0),
120	                static_cast<uint32_t>(0));
121	            DataCopyPad(inBuf, inputGm[srcOffset], copyParams);
122	            WaitMte2Done();
123	        } else {
124	            // FP16/BF16: need to cast
125	            // Use the second half of inBuf as temp for cast
126	            auto castDst = inBuf[alignedLen];
127	            DataCopyExtParams copyParams(
128	                static_cast<uint16_t>(1),
129	                static_cast<uint32_t>(sliceLen * sizeof(T)),
130	                static_cast<uint32_t>(0),
131	                static_cast<uint32_t>(0),
132	                static_cast<uint32_t>(0));
133	            DataCopyPad(castDst.ReinterpretCast<T>(), inputGm[srcOffset], copyParams);
134	            WaitMte2Done();
135	
136	            // Cast to FP32
137	            Cast(inBuf, castDst.ReinterpretCast<T>(), RoundMode::CAST_NONE, sliceLen);
138	            WaitVDone();
139	        }
140	    }
141	
142	    // If not largest (ascending), negate values so Sort gives ascending order
143	    if (tilingData.largest == 0) {
144	        Muls(inBuf, inBuf, -1.0f, alignedLen);
145	        WaitVDone();
146	    }
147	
148	    inQueue.EnQue(inBuf);
149	}
