151	template <typename T>
152	__aicore__ inline void KernelTopk<T>::Compute() {
153	    int32_t alignedLen = tilingData.alignedSliceLen;
154	    int32_t k = tilingData.k;
155	
156	    // Dequeue input
157	    auto inBuf = inQueue.DeQue<float>();
158	
159	    // Create index buffer (second half of inBuf)
160	    auto idxBuf = inBuf[alignedLen];
161	    CreateVecIndex(idxBuf.ReinterpretCast<int32_t>(), 0, alignedLen);
162	    WaitVDone();
163	
164	    // Sort the slice (descending order)
165	    uint32_t repeatTimes = alignedLen / 32;
166	    auto sortDst = inBuf;
167	    // Use index buffer area as temp for sort
168	    auto sortTmp = idxBuf;
169	
170	    Sort<float, true>(sortDst, inBuf, idxBuf.ReinterpretCast<uint32_t>(), sortTmp, repeatTimes);
171	    WaitVDone();
172	
173	    // Extract top-k values (first k elements after sort)
174	    auto outBuf = outQueue.AllocTensor<T>();
175	
176	    if constexpr (std::is_same_v<T, float>) {
177	        // FP32: direct copy
178	        DataCopy(outBuf, sortDst, k);
179	        WaitVDone();
180	    } else {
181	        // FP16/BF16: cast from FP32
182	        Cast(outBuf, sortDst, RoundMode::CAST_ROUND, k);
183	        WaitVDone();
184	    }
185	
186	    outQueue.EnQue(outBuf);
187	
188	    // Free input buffer
189	    inQueue.FreeTensor(inBuf);
190	}
