192	template <typename T>
193	__aicore__ inline void KernelTopk<T>::CopyOut(int32_t sliceIdx) {
194	    int64_t dstOffset = static_cast<int64_t>(sliceIdx) * tilingData.k;
195	    int32_t k = tilingData.k;
196	
197	    // Dequeue output
198	    auto outBuf = outQueue.DeQue<T>();
199	
200	    // Copy from UB to GM
201	    DataCopyExtParams copyParams(
202	        static_cast<uint16_t>(1),
203	        static_cast<uint32_t>(k * sizeof(T)),
204	        static_cast<uint32_t>(0),
205	        static_cast<uint32_t>(0),
206	        static_cast<uint32_t>(0));
207	    DataCopyPad(outputGm[dstOffset], outBuf, copyParams);
208	    WaitMte3Done();
209	
210	    // Free output buffer
211	    outQueue.FreeTensor(outBuf);
212	}
