214	template <typename T>
215	__aicore__ inline void KernelTopk<T>::Process() {
216	    int32_t blockIdx = GetBlockIdx();
217	    if (blockIdx >= tilingData.coreNum) {
218	        return;
219	    }
220	
221	    int32_t numSlices = (blockIdx == tilingData.coreNum - 1)
222	                            ? tilingData.lastCoreSlices
223	                            : tilingData.slicesPerCore;
224	
225	    for (int32_t i = 0; i < numSlices; ++i) {
226	        int32_t sliceIdx = blockIdx * tilingData.slicesPerCore + i;
227	        if (sliceIdx >= tilingData.totalSlices) {
228	            break;
229	        }
230	
231	        CopyIn(sliceIdx);
232	        Compute();
233	        CopyOut(sliceIdx);
234	    }
235	}
