#include "kernel_operator.h"
#include "topk_tiling.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t ONE_REPEAT_SORT_NUM = 32;
constexpr int32_t BLOCK_BYTES = 32;
constexpr float MIN_FP32 = -3.402823466e+38f;

__aicore__ inline int32_t AlignUp(int32_t elementNum, int32_t bytes)
{
    if (bytes == 0) return 0;
    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES / bytes;
}

// Wait for MTE2 (GM->UB) to complete
__aicore__ inline void WaitMte2Done() {
    event_t evt = static_cast<event_t>(
        GetTPipePtr()->FetchEventID(AscendC::HardEvent::MTE2_S));
    AscendC::SetFlag<AscendC::HardEvent::MTE2_S>(evt);
    AscendC::WaitFlag<AscendC::HardEvent::MTE2_S>(evt);
}

// Wait for MTE3 (UB->GM) to complete
__aicore__ inline void WaitMte3Done() {
    event_t evt = static_cast<event_t>(
        GetTPipePtr()->FetchEventID(AscendC::HardEvent::MTE3_S));
    AscendC::SetFlag<AscendC::HardEvent::MTE3_S>(evt);
    AscendC::WaitFlag<AscendC::HardEvent::MTE3_S>(evt);
}

// Wait for Vector compute to complete
__aicore__ inline void WaitVDone() {
    event_t evt = static_cast<event_t>(
        GetTPipePtr()->FetchEventID(AscendC::HardEvent::V_S));
    AscendC::SetFlag<AscendC::HardEvent::V_S>(evt);
    AscendC::WaitFlag<AscendC::HardEvent::V_S>(evt);
}

template <typename T>
class KernelTopk {
public:
    __aicore__ inline KernelTopk() {}
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int32_t sliceIdx);
    __aicore__ inline void Compute();
    __aicore__ inline void CopyOut(int32_t sliceIdx);

    // GM tensors
    GlobalTensor<T> inputGm;
    GlobalTensor<T> outputGm;

    // Tiling data
    TopkTilingData tilingData;

    // Queues and buffers
    TPipe pipe;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue;
    TBuf<TPosition::VECCALC> tempBuffer;
    TBuf<TPosition::VECCALC> sortedBuffer;
};

template <typename T>
__aicore__ inline void KernelTopk<T>::Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling) {
    auto* gmTiling = reinterpret_cast<__gm__ TopkTilingData*>(tiling);
    tilingData.totalSlices = gmTiling->totalSlices;
    tilingData.sliceLen = gmTiling->sliceLen;
    tilingData.k = gmTiling->k;
    tilingData.largest = gmTiling->largest;
    tilingData.coreNum = gmTiling->coreNum;
    tilingData.slicesPerCore = gmTiling->slicesPerCore;
    tilingData.lastCoreSlices = gmTiling->lastCoreSlices;
    tilingData.dtypeSize = gmTiling->dtypeSize;
    tilingData.alignedSliceLen = gmTiling->alignedSliceLen;

    inputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(input));
    outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(output));

    int32_t alignedLen = tilingData.alignedSliceLen;
    int32_t sortNum = ((alignedLen + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;

    // Buffer layout: [score (sortNum floats)] [index (sortNum floats)]
    int32_t inBufSize = sortNum * sizeof(float) * 2;
    int32_t outBufSize = tilingData.k * sizeof(T);
    int32_t tempBufSize = sortNum * sizeof(float) * 2;
    int32_t sortedBufSize = sortNum * sizeof(float) * 2;

    pipe.InitBuffer(inQueue, BUFFER_NUM, inBufSize);
    pipe.InitBuffer(outQueue, BUFFER_NUM, outBufSize);
    pipe.InitBuffer(tempBuffer, tempBufSize);
    pipe.InitBuffer(sortedBuffer, sortedBufSize);
}

template <typename T>
__aicore__ inline void KernelTopk<T>::CopyIn(int32_t sliceIdx) {
    int64_t srcOffset = static_cast<int64_t>(sliceIdx) * tilingData.sliceLen;
    int32_t sliceLen = tilingData.sliceLen;
    int32_t alignedLen = tilingData.alignedSliceLen;
    int32_t sortNum = ((alignedLen + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;

    auto inBuf = inQueue.AllocTensor<float>();

    // Fill with -inf for padding
    Duplicate(inBuf, MIN_FP32, sortNum * 2);
    WaitVDone();

    // Copy actual data from GM to UB
    if (sliceLen > 0) {
        if constexpr (std::is_same_v<T, float>) {
            DataCopyExtParams copyParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(sliceLen * sizeof(float)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0));
            DataCopyPadExtParams<float> padParams(false, 0, 0, 0.0f);
            DataCopyPad(inBuf, inputGm[srcOffset], copyParams, padParams);
            WaitMte2Done();
        } else {
            // FP16/BF16: copy to temp then cast
            auto castTemp = tempBuffer.Get<T>(sliceLen);
            DataCopyExtParams copyParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(sliceLen * sizeof(T)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0));
            DataCopyPadExtParams<T> padParams(false, 0, 0, static_cast<T>(0));
            DataCopyPad(castTemp, inputGm[srcOffset], copyParams, padParams);
            WaitMte2Done();

            Cast(inBuf, castTemp, RoundMode::CAST_NONE, sliceLen);
            WaitVDone();
        }
    }

    // If not largest (ascending), negate values so Sort gives ascending order
    if (tilingData.largest == 0) {
        Muls(inBuf, inBuf, -1.0f, alignedLen);
        WaitVDone();
    }

    // Pad remaining elements with -inf (already done by Duplicate above)

    inQueue.EnQue(inBuf);
}

template <typename T>
__aicore__ inline void KernelTopk<T>::Compute() {
    int32_t alignedLen = tilingData.alignedSliceLen;
    int32_t k = tilingData.k;
    int32_t sortNum = ((alignedLen + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
    int32_t repeatTimes = sortNum / ONE_REPEAT_SORT_NUM;

    auto inBuf = inQueue.DeQue<float>();

    // Create index buffer (second half of inBuf)
    auto indexBuf = inBuf[sortNum];
    CreateVecIndex(indexBuf.ReinterpretCast<int32_t>(), 0, sortNum);
    WaitVDone();

    // Concatenate score and index for Sort
    auto concatLocal = tempBuffer.Get<float>(sortNum * 2);
    Concat(concatLocal, inBuf, indexBuf, repeatTimes);
    WaitVDone();

    // Sort the slice (descending order)
    auto sortedLocal = sortedBuffer.Get<float>(sortNum * 2);
    auto indexU32 = indexBuf.ReinterpretCast<uint32_t>();
    Sort<float, true>(sortedLocal, concatLocal, indexU32, tempBuffer.Get<float>(sortNum * 2), repeatTimes);
    WaitVDone();

    // Extract top-k values
    auto outBuf = outQueue.AllocTensor<T>();
    auto scoreLocal = tempBuffer.Get<float>(sortNum);
    auto indexLocal = tempBuffer.Get<int32_t>(sortNum);
    Extract(scoreLocal, indexLocal.ReinterpretCast<uint32_t>(), sortedLocal, repeatTimes);
    WaitVDone();

    // Copy top-k values to output
    if constexpr (std::is_same_v<T, float>) {
        DataCopy(outBuf, scoreLocal, k);
        WaitVDone();
    } else {
        Cast(outBuf, scoreLocal, RoundMode::CAST_ROUND, k);
        WaitVDone();
    }

    outQueue.EnQue(outBuf);
    inQueue.FreeTensor(inBuf);
}

template <typename T>
__aicore__ inline void KernelTopk<T>::CopyOut(int32_t sliceIdx) {
    int64_t dstOffset = static_cast<int64_t>(sliceIdx) * tilingData.k;
    int32_t k = tilingData.k;

    auto outBuf = outQueue.DeQue<T>();

    DataCopyExtParams copyParams(
        static_cast<uint16_t>(1),
        static_cast<uint32_t>(k * sizeof(T)),
        static_cast<uint32_t>(0),
        static_cast<uint32_t>(0),
        static_cast<uint32_t>(0));
    DataCopyPad(outputGm[dstOffset], outBuf, copyParams);
    WaitMte3Done();

    outQueue.FreeTensor(outBuf);
}

template <typename T>
__aicore__ inline void KernelTopk<T>::Process() {
    int32_t blockIdx = GetBlockIdx();
    if (blockIdx >= tilingData.coreNum) {
        return;
    }

    int32_t numSlices = (blockIdx == tilingData.coreNum - 1)
                            ? tilingData.lastCoreSlices
                            : tilingData.slicesPerCore;

    for (int32_t i = 0; i < numSlices; ++i) {
        int32_t sliceIdx = blockIdx * tilingData.slicesPerCore + i;
        if (sliceIdx >= tilingData.totalSlices) {
            break;
        }

        CopyIn(sliceIdx);
        Compute();
        CopyOut(sliceIdx);
    }
}

