20	constexpr int32_t NUM_CORES = 20;
21	constexpr int32_t SORT_ALIGN = 32;  // Sort requires 32-element alignment
22	
23	static void computeTiling(TopkTilingData* t, int64_t totalSlices, int32_t sliceLen, int32_t k, int32_t largest, int32_t dtypeSize)
24	{
25	    *t = TopkTilingData{};
26	    t->totalSlices = totalSlices;
27	    t->sliceLen = sliceLen;
28	    t->k = k;
29	    t->largest = largest;
30	    t->dtypeSize = dtypeSize;
31	
32	    // Align sliceLen to 32 for Sort
33	    int32_t alignedLen = ((sliceLen + SORT_ALIGN - 1) / SORT_ALIGN) * SORT_ALIGN;
34	    t->alignedSliceLen = alignedLen;
35	
36	    // Calculate core allocation
37	    int32_t coreNum = std::min<int32_t>(NUM_CORES, static_cast<int32_t>(totalSlices));
38	    if (coreNum < 1) coreNum = 1;
39	    t->coreNum = coreNum;
40	
41	    int32_t slicesPerCore = static_cast<int32_t>((totalSlices + coreNum - 1) / coreNum);
42	    t->slicesPerCore = slicesPerCore;
43	    t->lastCoreSlices = static_cast<int32_t>(totalSlices - static_cast<int64_t>(slicesPerCore) * (coreNum - 1));
44	    if (t->lastCoreSlices <= 0) {
45	        t->lastCoreSlices = slicesPerCore;
46	    }
47	}
48	
49	at::Tensor topk(const at::Tensor& self, int64_t k, int64_t dim, bool largest)
50	{
51	    TORCH_CHECK(self.is_contiguous(), "topk: input must be contiguous");
52	    TORCH_CHECK(k > 0, "topk: k must be positive");
53	    TORCH_CHECK(k <= self.size(dim), "topk: k must be less than or equal to the size of the dimension");
54	
55	    int64_t ndim = self.dim();
56	    if (dim < 0) {
57	        dim = ndim + dim;
58	    }
59	    TORCH_CHECK(dim >= 0 && dim < ndim, "topk: dim out of range");
60	
61	    // Compute output shape
62	    std::vector<int64_t> outShape(self.sizes().begin(), self.sizes().end());
63	    outShape[dim] = k;
64	
65	    // Create output tensor
66	    auto output = at::empty(outShape, self.options());
67	
68	    // If dim is not the last dimension, we need to transpose to make it last
69	    at::Tensor inputContig = self;
70	    at::Tensor outputContig = output;
71	    bool needTranspose = (dim != ndim - 1);
72	
73	    if (needTranspose) {
74	        // Transpose dim to the last position
75	        std::vector<int64_t> perm(ndim);
76	        for (int64_t i = 0; i < ndim; ++i) {
77	            perm[i] = i;
78	        }
79	        perm[dim] = ndim - 1;
80	        perm[ndim - 1] = dim;
81	        inputContig = self.permute(perm).contiguous();
82	        // Output shape after transpose: same as input but last dim = k
83	        auto transposedOutShape = inputContig.sizes().vec();
84	        transposedOutShape[ndim - 1] = k;
85	        outputContig = at::empty(transposedOutShape, self.options());
86	    }
87	
88	    // Now dim is the last dimension
89	    int64_t sliceLen = inputContig.size(-1);
90	    int64_t totalSlices = inputContig.numel() / sliceLen;
91	
92	    // Flatten all but last dimension
93	    auto inputFlat = inputContig.reshape({totalSlices, sliceLen});
94	    auto outputFlat = outputContig.reshape({totalSlices, k});
95	
96	    // Compute tiling
97	    int32_t dtypeSize = 0;
98	    if (self.scalar_type() == at::kFloat) {
99	        dtypeSize = 4;
100	    } else if (self.scalar_type() == at::kHalf) {
101	        dtypeSize = 2;
102	    } else if (self.scalar_type() == at::kBFloat16) {
103	        dtypeSize = 2;
104	    } else {
105	        TORCH_CHECK(false, "topk: unsupported dtype");
106	    }
107	
108	    at::Tensor tilingCpu = at::empty(
109	        {static_cast<int64_t>(sizeof(TopkTilingData))},
110	        at::device(at::kCPU).dtype(at::kByte));
111	    auto* tiling = reinterpret_cast<TopkTilingData*>(tilingCpu.data_ptr());
112	    computeTiling(tiling, totalSlices, static_cast<int32_t>(sliceLen),
113	                  static_cast<int32_t>(k), largest ? 1 : 0, dtypeSize);
114	
115	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
116	
117	    uint32_t blockDim = static_cast<uint32_t>(tiling->coreNum);
118	
119	    // Launch kernel based on dtype
120	    if (self.scalar_type() == at::kFloat) {
121	        EXEC_KERNEL_CMD(topk_float, blockDim, inputFlat, outputFlat, tilingNpu);
122	    } else if (self.scalar_type() == at::kHalf) {
123	        EXEC_KERNEL_CMD(topk_half, blockDim, inputFlat, outputFlat, tilingNpu);
124	    } else if (self.scalar_type() == at::kBFloat16) {
125	        EXEC_KERNEL_CMD(topk_bfloat16, blockDim, inputFlat, outputFlat, tilingNpu);
126	    }
127	
128	    // If we transposed, need to transpose back
129	    if (needTranspose) {
130	        // Transpose last dimension back to original dim position
131	        std::vector<int64_t> permBack(ndim);
132	        for (int64_t i = 0; i < ndim; ++i) {
133	            permBack[i] = i;
134	        }
135	        permBack[ndim - 1] = dim;
136	        permBack[dim] = ndim - 1;
137	
138	        // Reshape outputFlat back to multi-dim before permute
139	        auto outputReshaped = outputFlat.reshape(inputContig.sizes());
140	        output = outputReshaped.permute(permBack).contiguous();
141	    } else {
142	        output = outputFlat.reshape(outShape);
143	    }
144	
145	    return output;
146	}
147	
148	}  // namespace ascend_kernel
