51	template <typename T>
52	class KernelTopk {
53	public:
54	    __aicore__ inline KernelTopk() {}
55	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling);
56	    __aicore__ inline void Process();
57	
58	private:
59	    __aicore__ inline void CopyIn(int32_t sliceIdx);
60	    __aicore__ inline void Compute();
61	    __aicore__ inline void CopyOut(int32_t sliceIdx);
62	
63	    // GM tensors
64	    GlobalTensor<T> inputGm;
65	    GlobalTensor<T> outputGm;
66	
67	    // Tiling data
68	    TopkTilingData tilingData;
69	
70	    // Queues and buffers
71	    TPipe pipe;
72	    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue;
73	    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue;
74	    TBuf<TPosition::VECCALC> tempBuffer;
75	    TBuf<TPosition::VECCALC> sortedBuffer;
76	};
77	
78	template <typename T>
79	__aicore__ inline void KernelTopk<T>::Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling) {
80	    auto* gmTiling = reinterpret_cast<__gm__ TopkTilingData*>(tiling);
81	    tilingData.totalSlices = gmTiling->totalSlices;
82	    tilingData.sliceLen = gmTiling->sliceLen;
83	    tilingData.k = gmTiling->k;
84	    tilingData.largest = gmTiling->largest;
85	    tilingData.coreNum = gmTiling->coreNum;
86	    tilingData.slicesPerCore = gmTiling->slicesPerCore;
87	    tilingData.lastCoreSlices = gmTiling->lastCoreSlices;
88	    tilingData.dtypeSize = gmTiling->dtypeSize;
89	    tilingData.alignedSliceLen = gmTiling->alignedSliceLen;
90	
91	    inputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(input));
92	    outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(output));
93	
94	    int32_t alignedLen = tilingData.alignedSliceLen;
95	    int32_t sortNum = ((alignedLen + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
96	
97	    // Buffer layout: [score (sortNum floats)] [index (sortNum floats)]
98	    int32_t inBufSize = sortNum * sizeof(float) * 2;
99	    int32_t outBufSize = tilingData.k * sizeof(T);
100	    int32_t tempBufSize = sortNum * sizeof(float) * 2;
101	    int32_t sortedBufSize = sortNum * sizeof(float) * 2;
102	
103	    pipe.InitBuffer(inQueue, BUFFER_NUM, inBufSize);
104	    pipe.InitBuffer(outQueue, BUFFER_NUM, outBufSize);
105	    pipe.InitBuffer(tempBuffer, tempBufSize);
106	    pipe.InitBuffer(sortedBuffer, sortedBufSize);
107	}
108	
109	template <typename T>
110	__aicore__ inline void KernelTopk<T>::CopyIn(int32_t sliceIdx) {
111	    int64_t srcOffset = static_cast<int64_t>(sliceIdx) * tilingData.sliceLen;
112	    int32_t sliceLen = tilingData.sliceLen;
113	    int32_t alignedLen = tilingData.alignedSliceLen;
114	    int32_t sortNum = ((alignedLen + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
115	
116	    auto inBuf = inQueue.AllocTensor<float>();
117	
118	    // Fill with -inf for padding
119	    Duplicate(inBuf, MIN_FP32, sortNum * 2);
120	    WaitVDone();
121	
122	    // Copy actual data from GM to UB
123	    if (sliceLen > 0) {
124	        if constexpr (std::is_same_v<T, float>) {
125	            DataCopyExtParams copyParams(
126	                static_cast<uint16_t>(1),
127	                static_cast<uint32_t>(sliceLen * sizeof(float)),
128	                static_cast<uint32_t>(0),
129	                static_cast<uint32_t>(0),
130	                static_cast<uint32_t>(0));
131	            DataCopyPadExtParams<float> padParams(false, 0, 0, 0.0f);
132	            DataCopyPad(inBuf, inputGm[srcOffset], copyParams, padParams);
133	            WaitMte2Done();
134	        } else {
135	            // FP16/BF16: copy to temp then cast
136	            auto castTemp = tempBuffer.Get<T>(sliceLen);
137	            DataCopyExtParams copyParams(
138	                static_cast<uint16_t>(1),
139	                static_cast<uint32_t>(sliceLen * sizeof(T)),
140	                static_cast<uint32_t>(0),
141	                static_cast<uint32_t>(0),
142	                static_cast<uint32_t>(0));
143	            DataCopyPadExtParams<T> padParams(false, 0, 0, static_cast<T>(0));
144	            DataCopyPad(castTemp, inputGm[srcOffset], copyParams, padParams);
145	            WaitMte2Done();
146	
147	            Cast(inBuf, castTemp, RoundMode::CAST_NONE, sliceLen);
148	            WaitVDone();
149	        }
150	    }
151	
152	    // If not largest (ascending), negate values so Sort gives ascending order
153	    if (tilingData.largest == 0) {
154	        Muls(inBuf, inBuf, -1.0f, alignedLen);
155	        WaitVDone();
156	    }
157	
158	    // Pad remaining elements with -inf (already done by Duplicate above)
159	
160	    inQueue.EnQue(inBuf);
161	}
162	
163	template <typename T>
164	__aicore__ inline void KernelTopk<T>::Compute() {
165	    int32_t alignedLen = tilingData.alignedSliceLen;
166	    int32_t k = tilingData.k;
167	    int32_t sortNum = ((alignedLen + ONE_REPEAT_SORT_NUM - 1) / ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
168	    int32_t repeatTimes = sortNum / ONE_REPEAT_SORT_NUM;
169	
170	    auto inBuf = inQueue.DeQue<float>();
171	
172	    // Create index buffer (second half of inBuf)
173	    auto indexBuf = inBuf[sortNum];
174	    CreateVecIndex(indexBuf.ReinterpretCast<int32_t>(), 0, sortNum);
175	    WaitVDone();
176	
177	    // Concatenate score and index for Sort
178	    auto concatLocal = tempBuffer.Get<float>(sortNum * 2);
179	    Concat(concatLocal, inBuf, indexBuf, repeatTimes);
180	    WaitVDone();
181	
182	    // Sort the slice (descending order)
183	    auto sortedLocal = sortedBuffer.Get<float>(sortNum * 2);
184	    auto indexU32 = indexBuf.ReinterpretCast<uint32_t>();
185	    auto sortTmp = tempBuffer.Get<float>(sortNum * 2);
186	    Sort<float, true>(sortedLocal, concatLocal, indexU32, sortTmp, repeatTimes);
187	    WaitVDone();
188	
189	    // Extract top-k values
190	    auto outBuf = outQueue.AllocTensor<T>();
191	    auto scoreLocal = tempBuffer.Get<float>(sortNum);
192	    auto indexLocal = tempBuffer.Get<int32_t>(sortNum);
193	    Extract(scoreLocal, indexLocal.ReinterpretCast<uint32_t>(), sortedLocal, repeatTimes);
194	    WaitVDone();
195	
196	    // Copy top-k values to output
197	    if constexpr (std::is_same_v<T, float>) {
198	        DataCopy(outBuf, scoreLocal, k);
199	        WaitVDone();
200	    } else {
201	        Cast(outBuf, scoreLocal, RoundMode::CAST_ROUND, k);
202	        WaitVDone();
203	    }
204	
205	    outQueue.EnQue(outBuf);
206	    inQueue.FreeTensor(inBuf);
207	}
208	
209	template <typename T>
210	__aicore__ inline void KernelTopk<T>::CopyOut(int32_t sliceIdx) {
211	    int64_t dstOffset = static_cast<int64_t>(sliceIdx) * tilingData.k;
212	    int32_t k = tilingData.k;
213	
214	    auto outBuf = outQueue.DeQue<T>();
215	
216	    DataCopyExtParams copyParams(
217	        static_cast<uint16_t>(1),
218	        static_cast<uint32_t>(k * sizeof(T)),
219	        static_cast<uint32_t>(0),
220	        static_cast<uint32_t>(0),
221	        static_cast<uint32_t>(0));
222	    DataCopyPad(outputGm[dstOffset], outBuf, copyParams);
223	    WaitMte3Done();
224	
225	    outQueue.FreeTensor(outBuf);
226	}
227	
228	template <typename T>
229	__aicore__ inline void KernelTopk<T>::Process() {
230	    int32_t blockIdx = GetBlockIdx();
231	    if (blockIdx >= tilingData.coreNum) {
232	        return;
233	    }
234	
235	    int32_t numSlices = (blockIdx == tilingData.coreNum - 1)
236	                            ? tilingData.lastCoreSlices
237	                            : tilingData.slicesPerCore;
238	
239	    for (int32_t i = 0; i < numSlices; ++i) {
240	        int32_t sliceIdx = blockIdx * tilingData.slicesPerCore + i;
241	        if (sliceIdx >= tilingData.totalSlices) {
242	            break;
243	        }
244	
245	        CopyIn(sliceIdx);
246	        Compute();
247	        CopyOut(sliceIdx);
248	    }
249	}
