23	static void computeTiling(TopkTilingData* t, int64_t totalSlices, int32_t sliceLen, int32_t k, int32_t largest, int32_t dtypeSize)
24	{
25	    *t = TopkTilingData{};
26	    t->totalSlices = totalSlices;
27	    t->sliceLen = sliceLen;
28	    t->k = k;
29	    t->largest = largest;
30	    t->dtypeSize = dtypeSize;
31	
32	    // Align sliceLen to 32 for Sort
33	    int32_t alignedLen = ((sliceLen + SORT_ALIGN - 1) / SORT_ALIGN) * SORT_ALIGN;
34	    t->alignedSliceLen = alignedLen;
35	
36	    // Calculate core allocation
37	    int32_t coreNum = std::min<int32_t>(NUM_CORES, static_cast<int32_t>(totalSlices));
38	    if (coreNum < 1) coreNum = 1;
39	    t->coreNum = coreNum;
40	
41	    int32_t slicesPerCore = static_cast<int32_t>((totalSlices + coreNum - 1) / coreNum);
42	    t->slicesPerCore = slicesPerCore;
43	    t->lastCoreSlices = static_cast<int32_t>(totalSlices - static_cast<int64_t>(slicesPerCore) * (coreNum - 1));
44	    if (t->lastCoreSlices <= 0) {
45	        t->lastCoreSlices = slicesPerCore;
